import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;

public class DateFormatter {
    private long date;
    private String formattedDate;
    private String format;

    public DateFormatter() {
        this.date = System.currentTimeMillis() / 1000L;
        this.format = "DD/MM/YYYY";
        convertDate();
    }

    public DateFormatter(long date) {
        this.date = date;
        this.format = "DD/MM/YYYY";
        convertDate();
    }

    public DateFormatter(long date, String format) {
        this.date = date;
        this.format = format;
        convertDate();
    }

    public long getDate() {
        return date;
    }

    public String getFormattedDate() {
        return formattedDate;
    }

    public String getFormat() {
        return format;
    }

    public void setDate(long date) {
        this.date = date;
        convertDate();
    }

    public void setFormat(String format) {
        this.format = format;
        convertDate();
    }

    private void convertDate() {
        if (format == null) {
            return;
        }

        String normalizedFormat = format.toUpperCase();

        Calendar calendar = Calendar.getInstance(
            TimeZone.getTimeZone("UTC")
        );

        Date dateObj = new Date(date * 1000L);
        calendar.setTime(dateObj);

        int day = calendar.get(Calendar.DAY_OF_MONTH);
        int month = calendar.get(Calendar.MONTH);
        int year = calendar.get(Calendar.YEAR);

        String dayStr = String.format("%02d", day);
        String yearStr = String.valueOf(year);

        if (normalizedFormat.equals("DD/MM/YYYY")) {
            formattedDate = dayStr + "/" +
                    String.format("%02d", month + 1) + "/" +
                    yearStr;

        } else if (normalizedFormat.equals("DD.MM.YYYY")) {
            formattedDate = dayStr + "." +
                    String.format("%02d", month + 1) + "." +
                    yearStr;

        } else if (normalizedFormat.equals("DD MONTH YYYY")) {
            String monthName = getMonth(month);

            formattedDate = dayStr + " " +
                    monthName + " " +
                    yearStr;
        }
    }

    private String getMonth(int month) {
        String[] months = {
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "",
            "September",
            "",
            "",
            ""
        };

        return months[month];
    }
}

